    adjBrk10:adjBrk10Eff,adjBrk12:adjBrk12Eff,adjBrk22:adjBrk22Eff,adjBrk24:adjBrk24Eff,adjBrk32:adjBrk32Eff,adjBrk35:adjBrk35Eff,
